import{_ as a,c as i,a2 as s,o as l}from"./chunks/framework.BnrAgU0Y.js";const u=JSON.parse('{"title":"安全最佳实践","description":"安全最佳实践","frontmatter":{"title":"安全最佳实践","description":"安全最佳实践","layout":"doc"},"headers":[],"relativePath":"langflow/configuration-security-best-practices.md","filePath":"langflow/configuration-security-best-practices.md"}'),t={name:"langflow/configuration-security-best-practices.md"};function n(r,e,o,c,p,d){return l(),i("div",null,e[0]||(e[0]=[s(`<h1 id="安全最佳实践" tabindex="-1">安全最佳实践 <a class="header-anchor" href="#安全最佳实践" aria-label="Permalink to &quot;安全最佳实践&quot;">​</a></h1><p>本文档概述了部署和管理 Langflow（Langflow 是一个编程库）时的安全最佳实践。</p><h2 id="secret-key-protection" tabindex="-1">Secret key protection <a class="header-anchor" href="#secret-key-protection" aria-label="Permalink to &quot;Secret key protection&quot;">​</a></h2><p>密钥保护</p><p>密钥在 Langflow 中对于加密敏感数据至关重要。请遵循以下指导原则：</p><ul><li><p>始终在生产环境中使用自定义密钥：</p><div class="language-plaintext vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_10 LANGFLOW_SECRET_KEY=your-secure-secret-key</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>以安全的方式存储密钥：</p><ul><li>使用环境变量或安全的密钥管理系统。</li><li>切勿将密钥提交到版本控制系统。</li><li>定期轮换密钥。</li></ul></li><li><p>使用默认的密钥存储位置：</p><ul><li>macOS: <code>~/Library/Caches/langflow/secret_key</code></li><li>Linux: <code>~/.cache/langflow/secret_key</code></li><li>Windows: <code>%USERPROFILE%\\AppData\\Local\\langflow\\secret_key</code></li></ul></li></ul><h2 id="api-密钥和凭证" tabindex="-1">API 密钥和凭证 <a class="header-anchor" href="#api-密钥和凭证" aria-label="Permalink to &quot;API 密钥和凭证&quot;">​</a></h2><ul><li>将 API 密钥和凭证存储为加密的全局变量。</li><li>对敏感信息使用 Credential 类型。</li><li>为能够查看/编辑凭证的用户实施正确的访问控制。</li><li>定期审核和更换 API 密钥。</li></ul><h2 id="数据库文件保护" tabindex="-1">数据库文件保护 <a class="header-anchor" href="#数据库文件保护" aria-label="Permalink to &quot;数据库文件保护&quot;">​</a></h2><ul><li><p><strong>将数据库存储在安全位置：</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANGFLOW_SAVE_DB_IN_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LANGFLOW_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/secure/path/to/config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p><strong>使用默认的数据库位置：</strong></p><ul><li>macOS/Linux: <code>PYTHON_LOCATION/site-packages/langflow/langflow.db</code></li><li>Windows: <code>PYTHON_LOCATION\\Lib\\site-packages\\langflow\\langflow.db</code></li></ul></li></ul>`,10)]))}const g=a(t,[["render",n]]);export{u as __pageData,g as default};
